arguments.content:
* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 10px;
  width: 800px;
  height: 600px;
  font-family: Arial, Helvetica, sans-serif;
  background: #1e1e2e;
  color: #eee;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
}

h1 {
  font-size: 22px;
  margin: 6px 0;
}

#hud {
  width: 480px;
  margin: 4px 0;
  text-align: center;
}

#hud [data-testid] {
  padding: 4px 8px;
  margin: 2px 0;
  background: #2a2a3c;
  border-radius: 4px;
  font-size: 14px;
}

#board {
  display: grid;
  grid-template-columns: repeat(8, 56px);
  grid-template-rows: repeat(5, 56px);
  gap: 2px;
  margin: 8px 0;
}

.cell {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: bold;
  border-radius: 4px;
  background: #3a3a4c;
  color: #eee;
}

.cell.wall  { background: #11111b; color: #555; }
.cell.floor { background: #3a3a4c; }
.cell.start { background: #45475a; }
.cell.key   { background: #f9e2af; color: #7a5c00; }
.cell.door  { background: #a87b4f; color: #fff; }
.cell.trap  { background: #f38ba8; color: #5a1030; }
.cell.exit  { background: #a6e3a1; color: #0a3d0a; }
.cell.player {
  background: #74c7ec;
  color: #06304a;
  box-shadow: 0 0 0 3px #89dceb inset;
}

#controls {
  margin: 6px 0;
}

button {
  font-size: 16px;
  padding: 6px 16px;
  margin: 0 6px;
  background: #89b4fa;
  color: #11111b;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

button:hover {
  background: #74c7ec;
}

#legend {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  font-size: 12px;
  margin-top: 6px;
}

.legend-cell {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 4px;
  font-weight: bold;
}

.hint {
  font-size: 12px;
  color: #aaa;
  margin-top: 4px;
}

(function () {
  'use strict';

  // Fixed 8x5 map. x = column, y = row.
  // S(1,1) start, K(1,3) key, D(4,1) door, T(4,3) trap, E(6,1) exit.
  var MAP = [
    ['#', '#', '#', '#', '#', '#', '#', '#'],
    ['#', 'S', '.', '.', 'D', '.', 'E', '#'],
    ['#', '.', '#', '.', '#', '.', '.', '#'],
    ['#', 'K', '.', '.', 'T', '.', '.', '#'],
    ['#', '#', '#', '#', '#', '#', '#', '#']
  ];
  var COLS = 8;
  var ROWS = 5;
  var START = { x: 1, y: 1 };
  var TOTAL_LIVES = 2;

  var status = 'menu';
  var player = { x: START.x, y: START.y };
  var lives = TOTAL_LIVES;
  var has_key = false;
  var door_open = false;
  var lifeSnapshot = { has_key: false, door_open: false };
  var message = '';

  var tick = 0;
  var seq = 0;
  var event_epoch = 0;
  var events = [];
  var ready = false;

  var board = document.getElementById('board');
  var scoreEl = document.querySelector('[data-testid="score"]');
  var statusEl = document.querySelector('[data-testid="status"]');
  var startBtn = document.getElementById('start-btn');
  var restartBtn = document.getElementById('restart-btn');

  function emit(type, payload) {
    tick++;
    seq++;
    var ev = { seq: seq, tick: tick, type: type };
    if (payload !== undefined) ev.payload = payload;
    events.push(ev);
    return ev;
  }

  function beginLife() {
    lifeSnapshot = { has_key: has_key, door_open: door_open };
  }

  function render() {
    board.innerHTML = '';
    for (var y = 0; y < ROWS; y++) {
      for (var x = 0; x < COLS; x++) {
        var ch = MAP[y][x];
        var cell = document.createElement('div');
        var type = 'floor';
        var label = '';
        if (ch === '#') { type = 'wall'; }
        else if (ch === 'S') { type = 'start'; label = 'S'; }
        else if (ch === 'K') { type = 'key'; label = 'K'; }
        else if (ch === 'D') { type = 'door'; label = 'D'; }
        else if (ch === 'T') { type = 'trap'; label = 'T'; }
        else if (ch === 'E') { type = 'exit'; label = 'E'; }
        cell.className = 'cell ' + type;
        cell.dataset.type = type;
        if (player.x === x && player.y === y) {
          cell.classList.add('player');
          cell.dataset.player = 'true';
          label = 'P';
        }
        cell.textContent = label;
        board.appendChild(cell);
      }
    }
  }

  function updateHud() {
    scoreEl.textContent =
      'Lives: ' + lives + '/' + TOTAL_LIVES +
      ' | Key: ' + (has_key ? 'Yes' : 'No') +
      ' | Door: ' + (door_open ? 'Open' : 'Locked');
    var msg = message ? ' - ' + message : '';
    statusEl.textContent = 'Status: ' + status.toUpperCase() + msg;
  }

  function getState() {
    return {
      status: status,
      player: { x: player.x, y: player.y },
      lives: lives,
      has_key: has_key,
      door_open: door_open
    };
  }

  function tryMove(dx, dy) {
    if (status !== 'playing') return;
    message = '';
    var nx = player.x + dx;
    var ny = player.y + dy;
    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      emit('wall_blocked');
      message = 'Blocked by wall';
      updateHud();
      return;
    }
    var ch = MAP[ny][nx];
    if (ch === '#') {
      emit('wall_blocked');
      message = 'Blocked by wall';
      updateHud();
      return;
    }
    if (ch === 'D' && !door_open) {
      if (!has_key) {
        emit('door_blocked');
        message = 'Door is locked';
        updateHud();
        return;
      }
      door_open = true;
      emit('door_opened');
      message = 'Door opened';
    }
    var from = { x: player.x, y: player.y };
    player = { x: nx, y: ny };
    emit('player_moved', { from: from, to: { x: nx, y: ny } });
    if (ch === 'K' && !has_key) {
      has_key = true;
      emit('key_collected');
      message = 'Key collected';
    }
    if (ch === 'T') {
      emit('trap_hit', { at: { x: nx, y: ny } });
      lives--;
      if (lives <= 0) {
        status = 'lost';
        emit('game_lost');
        message = 'Game over';
      } else {
        has_key = lifeSnapshot.has_key;
        door_open = lifeSnapshot.door_open;
        player = { x: START.x, y: START.y };
        beginLife();
        emit('player_respawned');
        message = 'Lost a life, back to start';
      }
      render();
      updateHud();
      return;
    }
    if (ch === 'E' && door_open) {
      status = 'won';
      emit('game_won');
      message = 'You escaped!';
    }
    render();
    updateHud();
  }

  function startGame() {
    if (status !== 'menu') return;
    status = 'playing';
    emit('game_started');
    message = '';
    render();
    updateHud();
  }

  function resetGame(seed) {
    status = 'menu';
    lives = TOTAL_LIVES;
    has_key = false;
    door_open = false;
    player = { x: START.x, y: START.y };
    lifeSnapshot = { has_key: false, door_open: false };
    message = '';
    tick = 0;
    seq = 0;
    event_epoch++;
    events = [];
    emit('game_reset', { seed: (seed === undefined ? null : seed) });
    render();
    updateHud();
  }

  function init() {
    resetGame(undefined);
    ready = true;
    render();
    updateHud();
  }

  startBtn.addEventListener('click', startGame);
  restartBtn.addEventListener('click', function () { resetGame(undefined); });

  window.addEventListener('keydown', function (e) {
    var handled = true;
    switch (e.code) {
      case 'ArrowUp': tryMove(0, -1); break;
      case 'ArrowDown': tryMove(0, 1); break;
      case 'ArrowLeft': tryMove(-1, 0); break;
      case 'ArrowRight': tryMove(1, 0); break;
      case 'KeyR': resetGame(undefined); break;
      default: handled = false;
    }
    if (handled) e.preventDefault();
  });

  window.__GAMETESTLAB__ = {
    protocol: 'gametestlab/2',
    isReady: function () { return ready; },
    reset: function (opts) {
      var seed = opts && opts.seed;
      resetGame(seed);
    },
    observe: function () {
      return {
        tick: tick,
        status: status,
        state: getState(),
        event_epoch: event_epoch,
        latest_event_seq: seq
      };
    },
    getEvents: function (opts) {
      var after = (opts && opts.afterSeq) ? opts.afterSeq : 0;
      return events.filter(function (ev) { return ev.seq > after; });
    }
  };

  init();
})();

{
  "schema_version": "gametestlab.game-manifest.v3",
  "entry_path": "index.html",
  "surface": "dom",
  "viewport": { "width": 800, "height": 600 },
  "controls": [
    {
      "action_id": "START",
      "actor": "primary",
      "device": "mouse",
      "key_event": "press",
      "selector": "#start-btn",
      "description": "开始游戏"
    },
    {
      "action_id": "UP",
      "actor": "primary",
      "device": "keyboard",
      "key_event": "press",
      "code": "ArrowUp",
      "description": "向上移动"
    },
    {
      "action_id": "DOWN",
      "actor": "primary",
      "device": "keyboard",
      "key_event": "press",
      "code": "ArrowDown",
      "description": "向下移动"
    },
    {
      "action_id": "LEFT",
      "actor": "primary",
      "device": "keyboard",
      "key_event": "press",
      "code": "ArrowLeft",
      "description": "向左移动"
    },
    {
      "action_id": "RIGHT",
      "actor": "primary",
      "device": "keyboard",
      "key_event": "press",
      "code": "ArrowRight",
      "description": "向右移动"
    },
    {
      "action_id": "RESTART",
      "actor": "primary",
      "device": "mouse",
      "key_event": "press",
      "selector": "#restart-btn",
      "description": "重开返回菜单"
    },
    {
      "action_id": "RESTART_KEY",
      "actor": "primary",
      "device": "keyboard",
      "key_event": "press",
      "code": "KeyR",
      "description": "键盘重开"
    }
  ],
  "hud_selectors": {
    "score": "[data-testid=\"score\"]",
    "status": "[data-testid=\"status\"]"
  },
  "state_schema": {
    "fields": {
      "status": { "type": "string", "description": "当前状态 menu/playing/won/lost" },
      "player": {
        "type": "object",
        "description": "玩家坐标",
        "fields": {
          "x": { "type": "integer", "description": "列坐标" },
          "y": { "type": "integer", "description": "行坐标" }
        }
      },
      "lives": { "type": "integer", "description": "剩余生命" },
      "has_key": { "type": "boolean", "description": "是否持有钥匙" },
      "door_open": { "type": "boolean", "description": "门是否打开" }
    },
    "required": ["status", "player", "lives", "has_key", "door_open"]
  },
  "event_schema": [
    {
      "type": "game_started",
      "description": "游戏开始",
      "payload_fields": {}
    },
    {
      "type": "player_moved",
      "description": "玩家移动",
      "payload_fields": {
        "from": { "type": "object", "description": "起点坐标" },
        "to": { "type": "object", "description": "终点坐标" }
      }
    },
    {
      "type": "wall_blocked",
      "description": "撞墙被阻挡",
      "payload_fields": {}
    },
    {
      "type": "door_blocked",
      "description": "锁门阻挡",
      "payload_fields": {}
    },
    {
      "type": "key_collected",
      "description": "取得钥匙",
      "payload_fields": {}
    },
    {
      "type": "door_opened",
      "description": "门被打开",
      "payload_fields": {}
    },
    {
      "type": "trap_hit",
      "description": "踩中陷阱",
      "payload_fields": {
        "at": { "type": "object", "description": "陷阱坐标" }
      }
    },
    {
      "type": "player_respawned",
      "description": "回到起点复活",
      "payload_fields": {}
    },
    {
      "type": "game_won",
      "description": "通关胜利",
      "payload_fields": {}
    },
    {
      "type": "game_lost",
      "description": "生命耗尽失败",
      "payload_fields": {}
    },
    {
      "type": "game_reset",
      "description": "重置回菜单",
      "payload_fields": {
        "seed": { "type": "null", "description": "随机种子(本作固定地图)" }
      }
    }
  ],
  "bridge": {
    "protocol": "gametestlab/2",
    "evidence_only": true,
    "actions_via_real_input": true
  }
}
